  /// Error growth rate (km/day)
  ERROR_GROWTH_RATE:double;
  /// Energy dissipation rate
  EDR:double;
  /// True if ballistic coefficient was estimated
  BALLISTIC_COEFF_EST:bool;
  /// Ballistic coefficient model
